parameters.responseBody:
=[
  {
    "Total Code files": 1,
    "5 Metrics average score": {
      "Code Readability": {{ $json['Code Readability'] }},
      "Code Efficiency": {{ $json['Code Efficiency'] }},
      "Error Handling": {{ $json['Error Handling'] }},
      "Maintainability": {{ $json.Maintainability }},
      "Best Practices & Standards": {{ $json['Best Practices & Standards'] }}
    },
    "Overall Score": {{ $json['Overall Score'] }}
  }
]

parameters.jsCode:
const items = $input.all();

return items.map(item => {
  const text = item.json.text || '';

  const metricNames = [
    'Code Readability',
    'Code Efficiency',
    'Error Handling',
    'Maintainability',
    'Best Practices & Standards'
  ];

  const scores = {};

  // Split the LLM response into individual lines
  const lines = text.split(/\r?\n/);

  for (const metric of metricNames) {

    // Find the table row containing the metric name
    const row = lines.find(line =>
      line.trim().startsWith('|') &&
      line.toLowerCase().includes(metric.toLowerCase())
    );

    if (!row) {
      throw new Error('Metric row not found: ' + metric);
    }

    // Split the row into table columns
    const cells = row.split('|').map(cell => cell.trim());

    // The last non-empty cell contains the score
    const scoreCell = cells.filter(cell => cell !== '').pop();

    // Extract the numeric score, including bold Markdown formatting
    const scoreMatch = scoreCell.match(
      /\*{0,2}\s*(\d+(?:\.\d+)?)\s*\*{0,2}/
    );

    if (!scoreMatch) {
      throw new Error(
        'Score not found for: ' + metric +
        '. Table row: ' + row
      );
    }

    scores[metric] = Number(scoreMatch[1]);
  }

  // Extract the Overall Score, for example: **71 / 100**
  const overallMatch = text.match(
    /Overall Score[\s\S]{0,150}?\*\*\s*(\d+(?:\.\d+)?)\s*\/\s*100\s*\*\*/i
  );

  if (!overallMatch) {
    throw new Error('Overall Score not found in LLM response.');
  }

  scores['Overall Score'] = Number(overallMatch[1]);

  return {
    json: scores
  };
});
